style.css:
@-moz-document domain("pinterest.com") {
/* Background color */
  body {
    background-color: #7d7bb1 !important;
    color: #ffffff !important;
    font-family: "Coolvetica", sans-serif !important;
  }

  /* Style the text */
  h1, h2, h3, h4, h5, h6, p, span, a, div {
    color: #ffffff !important;
    font-family: "Coolvetica", sans-serif !important;
  }

  /* Style buttons */
  button {
    background-color: #ffffff !important;
    color: #7d7bb1 !important;
    border: none;
    transition: 0.3s;
  }

  /* Hover effect */
  button:hover {
    background-color: #7d7bb1 !important;
    color: #ffffff !important;
  }
}
